import React from "react";
import StatCard from "../components/StatCard";
import DonutChart from "../components/DonutChart";
import ProgressBar from "../components/ProgressBar";
import { BUDGETS, DONUT_DATA } from "../data/mockData";

const INSIGHTS = [
  {
    type: "warn" as const,
    icon: "⚠️",
    title: "Entertainment budget exceeded",
    body: "You've spent $210 of your $200 limit. Consider cutting a streaming subscription.",
    bg: "bg-yellow-50",
    border: "border-yellow-100",
  },
  {
    type: "good" as const,
    icon: "✅",
    title: "Great savings rate!",
    body: "Your 36.7% savings rate is above average. Keep it up to hit your annual $26,000 goal.",
    bg: "bg-emerald-50",
    border: "border-emerald-100",
  },
  {
    type: "info" as const,
    icon: "💡",
    title: "Weekend food spending is higher",
    body: "You spend 23% more on food on weekends. Meal prepping could save ~$80/month.",
    bg: "bg-blue-50",
    border: "border-blue-100",
  },
  {
    type: "info" as const,
    icon: "📈",
    title: "Income growing steadily",
    body: "Your income increased 15.4% since January. Consider increasing your investment allocation.",
    bg: "bg-blue-50",
    border: "border-blue-100",
  },
];

const Analytics: React.FC = () => (
  <div className="p-4 md:p-6 max-w-6xl mx-auto">
    <div className="mb-5">
      <h1 className="text-xl font-medium text-gray-900">Analytics & Reports</h1>
      <p className="text-sm text-gray-400 mt-0.5">June 2024 · Detailed spending insights</p>
    </div>

    {/* Summary cards */}
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5">
      <StatCard label="Total Spending" value="$3,800" change="This month" trend="neutral" />
      <StatCard label="Avg Daily Spend" value="$126.67" change="June average" trend="neutral" />
      <StatCard label="Highest Month" value="$4,200" change="March 2024" trend="neutral" />
      <StatCard label="Savings Rate" value="36.7%" change="vs 28% avg" trend="up" valueColor="green" />
    </div>

    {/* Charts row */}
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-4">
      {/* Donut */}
      <div className="bg-white border border-gray-100 rounded-xl p-5">
        <h2 className="text-sm font-medium text-gray-700 mb-4">Expense Breakdown</h2>
        <DonutChart data={DONUT_DATA} />
      </div>

      {/* Category utilization */}
      <div className="bg-white border border-gray-100 rounded-xl p-5">
        <h2 className="text-sm font-medium text-gray-700 mb-4">Category Utilization</h2>
        <div className="flex flex-col gap-5">
          {BUDGETS.map((b, i) => {
            const pct = Math.round((b.spent / b.limit) * 100);
            const over = pct > 100;
            return (
              <div key={i}>
                <div className="flex justify-between items-center mb-2 text-sm">
                  <span className="font-medium text-gray-700">{b.category}</span>
                  <span className={`font-medium ${over ? "text-red-500" : "text-gray-500"}`}>
                    {pct}%
                  </span>
                </div>
                <ProgressBar value={pct} color={b.color} height={10} overBudget={over} />
                {over && (
                  <p className="text-xs text-red-500 mt-1.5 flex items-center gap-1">
                    ⚠ {pct - 100}% over budget limit
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>

    {/* Smart Insights */}
    <div className="bg-white border border-gray-100 rounded-xl p-5">
      <h2 className="text-sm font-medium text-gray-700 mb-4">Smart Insights</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {INSIGHTS.map((ins, i) => (
          <div
            key={i}
            className={`flex gap-3 p-3.5 rounded-xl border ${ins.bg} ${ins.border}`}
          >
            <span className="text-xl shrink-0 mt-0.5">{ins.icon}</span>
            <div>
              <p className="text-sm font-medium text-gray-800 mb-0.5">{ins.title}</p>
              <p className="text-xs text-gray-500 leading-relaxed">{ins.body}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  </div>
);

export default Analytics;
